			name: "right operand is zero",
			a:    5,
			b:    0,
			want: 5,
		},
		{
			name: "zero plus negative",
			a:    0,
			b:    -5,
			want: -5,
		},
		{
			name: "negative plus zero",
			a:    -5,
			b:    0,
			want: -5,
		},
